template<typename E> struct Expression {};

// Node representing vector addition (AST Composite Node)
template<typename L, typename R>
struct VectorAdd : public Expression<VectorAdd<L, R>> {
    const L& lhs;
    const R& rhs;

    VectorAdd(const L& l, const R& r) : lhs(l), rhs(r) {}

    // Lazy evaluation: Calculation occurs only when indexed
    auto operator[](size_t i) const { return lhs[i] + rhs[i]; }
};

// Operator overload constructs the AST (Abstract Syntax Tree)
template<typename L, typename R>
auto operator+(const Expression<L>& l, const Expression<R>& r) {
    return VectorAdd<L, R>(static_cast<const L&>(l),
                          static_cast<const R&>(r));
}

// Vector class (The sink that triggers evaluation)
class Vector : public Expression<Vector> {
